function esc(s){
  return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function metaTag(name,content){ return '<meta name="'+esc(name)+'" content="'+esc(content)+'">'; }
function ogTag(prop,content){ return '<meta property="'+esc(prop)+'" content="'+esc(content)+'">'; }
function buildMeta(opt){
  opt=opt||{};
  var title=String(opt.title||'').trim();
  if(!title) throw new Error('标题不能为空');
  var desc=String(opt.desc||'').trim();
  var L=[];
  L.push('<!-- 基础 -->');
  L.push('<meta charset="UTF-8">');
  L.push('<meta name="viewport" content="width=device-width, initial-scale=1.0">');
  L.push('<title>'+esc(title)+'</title>');
  if(desc) L.push(metaTag('description',desc));
  L.push('');
  L.push('<!-- Open Graph -->');
  L.push(ogTag('og:type',opt.ogType||'website'));
  L.push(ogTag('og:title',title));
  if(desc) L.push(ogTag('og:description',desc));
  if(opt.url) L.push(ogTag('og:url',opt.url));
  if(opt.image) L.push(ogTag('og:image',opt.image));
  if(opt.siteName) L.push(ogTag('og:site_name',opt.siteName));
  if(opt.lang) L.push(ogTag('og:locale',String(opt.lang).replace('-','_')));
  L.push('');
  L.push('<!-- Twitter Card -->');
  L.push(metaTag('twitter:card',opt.twitterCard||'summary_large_image'));
  L.push(metaTag('twitter:title',title));
  if(desc) L.push(metaTag('twitter:description',desc));
  if(opt.image) L.push(metaTag('twitter:image',opt.image));
  if(opt.twitterHandle){
    var h=String(opt.twitterHandle).trim(); if(h && h[0]!=='@') h='@'+h;
    L.push(metaTag('twitter:site',h));
  }
  return L.join('\n');
}
function checkLengths(opt){
  var warns=[];
  var t=String((opt&&opt.title)||''), d=String((opt&&opt.desc)||'');
  if(t.length>60) warns.push('标题超过 60 字符（'+t.length+'），搜索结果可能被截断');
  if(d.length>160) warns.push('描述超过 160 字符（'+d.length+'），搜索结果可能被截断');
  if(d && d.length<50) warns.push('描述少于 50 字符，建议补充');
  return warns;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { esc:esc, metaTag:metaTag, ogTag:ogTag, buildMeta:buildMeta, checkLengths:checkLengths };
}
if (typeof window !== 'undefined') {
  window.MetaForgePure = { esc:esc, metaTag:metaTag, ogTag:ogTag, buildMeta:buildMeta, checkLengths:checkLengths };
}
